package com.asif.studentmanagement.controller;
import com.asif.studentmanagement.model.Student; import com.asif.studentmanagement.repository.StudentRepository; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*;
@Controller public class StudentController { private final StudentRepository repository; public StudentController(StudentRepository repository){this.repository=repository;} @GetMapping("/") public String list(@RequestParam(required=false) String search,Model model){model.addAttribute("students",search==null||search.isBlank()?repository.findAll():repository.findByNameContainingIgnoreCase(search)); model.addAttribute("search",search==null?"":search); return "students";} @GetMapping("/students/new") public String newStudent(Model model){model.addAttribute("student",new Student());return "student-form";} @PostMapping("/students/save") public String save(@Valid @ModelAttribute("student") Student student,BindingResult result){if(result.hasErrors())return "student-form";repository.save(student);return "redirect:/";} @GetMapping("/students/edit/{id}") public String edit(@PathVariable Long id,Model model){model.addAttribute("student",repository.findById(id).orElseThrow());return "student-form";} @GetMapping("/students/delete/{id}") public String delete(@PathVariable Long id){repository.deleteById(id);return "redirect:/";} }
